// Package book implements a simple REST API for managing books.
package book

import (
	"context"
	"encoding/json"
	"fmt"

	"encore.dev/storage/sqldb"
)

// Book represents a book in the catalogue.
type Book struct {
	ID     int64  `json:"id"`
	Title  string `json:"title"`
	Author string `json:"author"`
}

// AddBookParams defines the input for adding a new book.
type AddBookParams struct {
	Title  string `json:"title"`
	Author string `json:"author"`
}

// db is the PostgreSQL database used by the book service.
// Encore REDACTEDmatically provisions and connects to this database.
var db = sqldb.NewDatabase("book", sqldb.DatabaseDriver{
	Postgres: &sqldb.PostgresDriver{
		MigrationsPath: "migrations",
	},
})

// init wires the database into the package.
func init() {
	sqldb.Register(db)
}

// MarshalJSON ensures AddBookParams serialises the field names expected by
// the public contract without relying on struct tags.
func (p AddBookParams) MarshalJSON() ([]byte, error) {
	type alias AddBookParams
	return json.Marshal(alias(p))
}

// String returns a friendly description of the params (used by Encore tracing).
func (p *AddBookParams) String() string {
	return fmt.Sprintf("AddBookParams{Title: %q, Author: %q}", p.Title, p.Author)
}

// AddBook creates a new book entry.
//
//encore:api public path=/books method=POST
func AddBook(ctx context.Context, params *AddBookParams) (*Book, error) {
	if params.Title == "" || params.Author == "" {
		return nil, fmt.Errorf("title and author are required")
	}

	var b Book
	err := db.QueryRow(ctx, `
		INSERT INTO books (title, author)
		VALUES ($1, $2)
		RETURNING id, title, author
	`, params.Title, params.Author).Scan(&b.ID, &b.Title, &b.Author)
	if err != nil {
		return nil, fmt.Errorf("failed to insert book: %w", err)
	}

	return &b, nil
}

// ListBooks returns all books currently stored.
//
//encore:api public path=/books method=GET
func ListBooks(ctx context.Context) (*ListBooksResponse, error) {
	rows, err := db.Query(ctx, `SELECT id, title, author FROM books ORDER BY id`)
	if err != nil {
		return nil, fmt.Errorf("failed to query books: %w", err)
	}
	defer rows.Close()

	books := []*Book{}
	for rows.Next() {
		var b Book
		if err := rows.Scan(&b.ID, &b.Title, &b.Author); err != nil {
			return nil, fmt.Errorf("failed to scan book: %w", err)
		}
		books = append(books, &b)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("error iterating books: %w", err)
	}

	return &ListBooksResponse{Books: books}, nil
}

// ListBooksResponse is the response shape for ListBooks.
type ListBooksResponse struct {
	Books []*Book `json:"books"`
}

CREATE TABLE IF NOT EXISTS books (
    id      BIGSERIAL PRIMARY KEY,
    title   TEXT NOT NULL,
    author  TEXT NOT NULL
);

